import{_ as a,o as e,c as r,al as d}from"./chunks/framework.BawR2jEz.js";const m=JSON.parse('{"title":"Быстрые настройки","description":"Модальное окно для управления глобальными ресурсами проекта — стили, скрипты, спрайты, переменные, палитры и UI Kit.","frontmatter":{"title":"Быстрые настройки","description":"Модальное окно для управления глобальными ресурсами проекта — стили, скрипты, спрайты, переменные, палитры и UI Kit."},"headers":[],"relativePath":"fast-settings/index.md","filePath":"fast-settings/index.md"}'),h={name:"fast-settings/index.md"};function l(i,t,o,s,n,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="быстрые-настроики" tabindex="-1">Быстрые настройки <a class="header-anchor" href="#быстрые-настроики" aria-label="Permalink to &quot;Быстрые настройки&quot;">​</a></h1><p>Быстрые настройки — модальное окно для управления всем глобальным: тем, что действует на весь проект, а не на отдельный блок или рубрику.</p><h2 id="доступ" tabindex="-1">Доступ <a class="header-anchor" href="#доступ" aria-label="Permalink to &quot;Доступ&quot;">​</a></h2><p>Нажмите кнопку <strong>Быстрые настройки</strong> в верхнем меню админ-панели.</p><p>Состав окна зависит от прав: каждая вкладка показывается, только если роли выдан доступ к соответствующему разделу. У пользователя с урезанной ролью вкладок будет меньше.</p><h2 id="вкладки" tabindex="-1">Вкладки <a class="header-anchor" href="#вкладки" aria-label="Permalink to &quot;Вкладки&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Вкладка</th><th>Описание</th></tr></thead><tbody><tr><td>Стили</td><td>Всё, что касается оформления, — разбито на подвкладки, см. ниже</td></tr><tr><td><a href="./scripts.html">Скрипты</a></td><td>Глобальные JavaScript-скрипты</td></tr><tr><td><a href="./svg-sprites.html">SVG-спрайты</a></td><td>Коллекции иконок для вызова через <code>ex.ico()</code></td></tr><tr><td><a href="./components/">Компоненты</a></td><td>Глобальные компоненты, доступные на любой странице</td></tr><tr><td><a href="./global-fields.html">Глобальные поля</a></td><td>Поля, доступные на всех страницах через <code>ex.global_fld()</code></td></tr><tr><td><a href="./preset-fields.html">Пресеты полей</a></td><td>Готовые наборы настроек полей</td></tr></tbody></table><h3 id="внутри-вкладки-«стили»" tabindex="-1">Внутри вкладки «Стили» <a class="header-anchor" href="#внутри-вкладки-«стили»" aria-label="Permalink to &quot;Внутри вкладки «Стили»&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Подвкладка</th><th>Описание</th></tr></thead><tbody><tr><td><a href="./palettes.html">Palettes</a></td><td>Палитры: базовый цвет и его оттенки</td></tr><tr><td><a href="./schemes.html">Schemes</a></td><td>Схемы: раздача цветов по ролям</td></tr><tr><td><a href="./variables.html">Font-Family</a></td><td>Шрифты</td></tr><tr><td><a href="./variables.html">Border-radius</a></td><td>Скругления</td></tr><tr><td><a href="./variables.html">Space</a></td><td>Отступы</td></tr><tr><td><a href="./variables.html">Box-shadow</a></td><td>Тени</td></tr><tr><td><a href="./variables.html">Breakpoints</a></td><td>Точки адаптива</td></tr><tr><td><a href="./ui-kit/">UI Kit</a></td><td>Конструктор кнопок, полей форм, бейджей и типографики</td></tr><tr><td><a href="./styles.html">SCSS Стили</a></td><td>Глобальные SCSS: миксины, функции, базовая типографика, порядок сборки CSS</td></tr></tbody></table><h2 id="импорт-и-экспорт" tabindex="-1">Импорт и экспорт <a class="header-anchor" href="#импорт-и-экспорт" aria-label="Permalink to &quot;Импорт и экспорт&quot;">​</a></h2><p>Настройки переносятся между проектами: при экспорте вы отмечаете, что именно выгрузить — палитры, схемы, переменные по группам, SCSS-стили, скрипты, спрайты, компоненты, глобальные поля, пресеты полей, — и результат копируется в буфер обмена. Импорт вставляет скопированное на другом сайте.</p><p>Если спрайт, глобальное поле или пресет с таким же именем уже есть, exDoc спросит, перезаписывать ли его.</p><h2 id="сохранение" tabindex="-1">Сохранение <a class="header-anchor" href="#сохранение" aria-label="Permalink to &quot;Сохранение&quot;">​</a></h2><p>Изменения во всех вкладках сохраняются кнопкой <strong>Сохранить и закрыть</strong>. После сохранения стилей автоматически запускается SCSS-компиляция.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./../editor/">Редактор</a> — использование переменных в стилях</li><li><a href="./../settings/roles.html">Настройки → Роли</a> — кому какие вкладки видны</li></ul>',16)])])}const p=a(h,[["render",l]]);export{m as __pageData,p as default};
